ext={\"primary\":{\"estimate\":c[\"rho-primary\"][\"expected\"],\"ci95_donor_percentile\":c[\"primary-interval\"][\"expected\"],\"n_fixed_genes\":207,\"n_models_analyzed\":148,\"n_donors_analyzed\":144},\"secondary_holm_family\":{},\"stability_not_decision\":{\"leave_one_model_out\":{\"a\":-0.166,\"b\":-0.082}}}
