null-calibrated -0.209; TMOD-alias -0.145; alternate-library -0.151; unadjusted -0.217.
(-0.166...-0.082)
fixed 207-gene
207 with external displacement
(148 models,
to 142 patients
250-gene evidence
144 covariate
(7 and 8 FDR
\"\"\"
def check(text): return ns[\"validate\"](text,ext,elig,aman)
assert all(x[\"matches\"] for x in check(base).values())

cases=[]
for value in (\"148/2\",\"999/250\"):
 for pattern in (\"fixed {v}-gene\",\"within the {v}-gene\",\"{v} with external displacement\",\"({v} models,\",\"Additional {v} Sanger organoid models\",\"{v} models =\",\"to {v} patients\",\"/ {v} patients\",\"= **{v} patients\",\"{v}-gene evidence\",\"{v} panel genes\",\"{v} selected genes\",\"{v}-gene panel (outcome\",\"{v} covariate\"):
  cases.append((\"slash \"+pattern.format(v=value),base+pattern.format(v=value)))
for label in (\"null-calibrated\",\"TMOD-alias\",\"alternate-library\",\"unadjusted\"):
 for malformed in (\"≈-0.999\",\" ≈ -0.999\",\"=-0.999\",\" -0.999oops\", \"\"):
  cases.append((\"secondary \"+label+malformed,base+label+malformed))
for punct in (\".\",\",\",\";\",\":\",\")\"):
 for label in (\"ρ =\",\"null-calibrated\",\"TMOD-alias\",\"alternate-library\",\"unadjusted\"):
  val = \"-0.146\" if label==\"ρ =\" else c[label][\"expected\"]
  cases.append((\"repeated \"+label+punct+punct,base+label+\" \"+val+punct+punct))
for interval in (\"[NaN, NaN]\",\"[,]\",\"[-0.175, -0.114junk]\",\"[junk-0.175, -0.114]\",\"[-0.175, -0.114,]\",\"[-0.175, -0.114, -0.114]\",\"[[-0.175, -0.114]]\"):
 cases.append((\"bracket \"+interval,base+interval))
unexpected=[]
for name,text in cases:
 out=check(text)
 if all(v[\"matches\"] for v in out.values()): unexpected.append(name)
print(json.dumps({\"must_reject_cases\":len(cases),\"rejected\":len(cases)-len(unexpected),\"unexpected_acceptances\":unexpected}))
'"

